import './Dashboard.css';

type StatCardProps = {
  label: string;
  value: string;
};

function StatCard({ label, value }: StatCardProps) {
  return (
    <li className="stat-card">
      <p className="stat-card__label">{label}</p>
      <p className="stat-card__value">{value}</p>
    </li>
  );
}

export default function Dashboard() {
  return (
    <div className="dashboard">
      <h2 className="dashboard__title">Weekly insights</h2>
      <ul className="dashboard__stats">
        <StatCard label="Sessions" value="342" />
        <StatCard label="Avg time" value="18.2" />
        <StatCard label="Peak day" value="Friday" />
      </ul>
      <button className="primary-button" type="button">
        <span className="primary-button__text">View report</span>
      </button>
    </div>
  );
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap');

/* Scoped reset — Figma has no default margins */
.dashboard, .dashboard *, .dashboard *::before, .dashboard *::after { box-sizing: border-box; }
.dashboard :where(h1, h2, h3, p, ul, li, figure) { margin: 0; padding: 0; }
.dashboard :where(button) { border: 0; background: none; padding: 0; font: inherit; color: inherit; cursor: pointer; }
.dashboard :where(a) { color: inherit; text-decoration: none; }
.dashboard :where(img) { display: block; }

.dashboard {
  display: flex;
  flex-direction: column;
  padding: 24px;
  gap: 16px;
  width: 420px;
  background: #FFFFFF;
  font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.dashboard__title {
  color: #111827;
  font-size: 18px;
  font-weight: 600;
  line-height: 20px;
  white-space: nowrap;
}

.dashboard__stats {
  display: flex;
  flex-direction: row;
  gap: 12px;
  align-self: stretch;
  padding: 0;
  margin: 0;
  list-style: none;
}

.stat-card {
  display: flex;
  flex-direction: column;
  padding: 16px;
  gap: 4px;
  border-radius: 12px;
  background: #F9FAFB;
  flex: 1 0 0;
}

.stat-card__label {
  color: #6B7280;
  font-size: 12px;
  font-weight: 400;
  line-height: 20px;
  white-space: nowrap;
}

.stat-card__value {
  color: #111827;
  font-size: 20px;
  font-weight: 700;
  line-height: 20px;
  white-space: nowrap;
}

.primary-button {
  display: flex;
  flex-direction: row;
  padding: 12px 24px;
  border-radius: 8px;
  background: #0D99FF;
  justify-content: center;
}

.primary-button__text {
  color: #FFFFFF;
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  white-space: nowrap;
}
